(function(){if(window.__billdrTicker)return;window.__billdrTicker=1;var SPEED=60,builtW=0;function css(){if(document.getElementById('btk'))return;var s=document.createElement('style');s.id='btk';s.textContent='@keyframes btkScroll{from{transform:translateX(0)}to{transform:translateX(-50%)}}.hero_ticker-marquee{-webkit-mask-image:linear-gradient(90deg,transparent 0,#000 6%,#000 94%,transparent 100%);mask-image:linear-gradient(90deg,transparent 0,#000 6%,#000 94%,transparent 100%)}.hero_ticker-marquee:hover .hero_ticker-list{animation-play-state:paused}@media(prefers-reduced-motion:reduce){.hero_ticker-list{animation:none!important}}';document.head.appendChild(s);}function build(){var tracks=document.querySelectorAll('.hero_ticker-list');for(var i=0;i<tracks.length;i++){var t=tracks[i],m=t.parentElement;if(!m)continue;if(!t.getAttribute('data-orig'))t.setAttribute('data-orig',t.innerHTML);t.style.animation='none';t.innerHTML=t.getAttribute('data-orig');var base=t.scrollWidth;if(!base)continue;var cw=m.clientWidth||base;var per=Math.max(2,Math.ceil((cw+base)/base));var set=t.innerHTML,html='';for(var k=0;k<per*2;k++)html+=set;t.innerHTML=html;var half=t.scrollWidth/2;t.style.animation='btkScroll '+(half/SPEED)+'s linear infinite';}builtW=window.innerWidth;}function init(){css();build();var to;window.addEventListener('resize',function(){if(window.innerWidth===builtW)return;clearTimeout(to);to=setTimeout(build,300);});}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();